/* Continuous native building fades, host acknowledgement, password scroll and
 * cold-title license gate. Host presentation never changes native machine data. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-web.c"
#include "em_web_menu_select.h"
#include "em_web_campaign.h"
#include <sys/stat.h>
static CPU c,before;static DuneMouse mouse;static FILE*trace,*events;static uint64_t last=UINT64_MAX;
static void check(int ok,const char*m){if(!ok){fprintf(stderr,"FAIL %s pc%x reason%s %s\n",m,c.pc,c.reason?c.reason:"",em_web_campaign_report(&c));exit(1);}}
static void load(const char*p){FILE*f=fopen(p,"rb");check(f&&fread(&c,sizeof c,1,f)==1,"source snapshot");fclose(f);c.rom=rom_data;c.rom_size=sizeof rom_data;c.reason=0;c.fault=0;c.audio_mode=AUDIO_MUTE;memset(c.pad_buttons,0,sizeof c.pad_buttons);memset(&mouse,0,sizeof mouse);mouse.enabled=1;em_web_menu_select_reset_state();memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);last=UINT64_MAX;}
static void step(void){switch(c.pc){case 0x287dc:case 0x287ea:case 0x287f0:case 0x2884e:case 0x28854:case 0x28884:case 0x2895c:case 0x2896e:case 0x28974:case 0x289f4:case 0x289fa:case 0x28a18:case 0x28a26:case 0x28a2c:case 0x28a8a:case 0x28a90:case 0x28ce8:case 0x28cfa:case 0x28d00:case 0x28d5c:case 0x28d62:case 0x628:case 0x6c8:case 0x6c6:case 0x786:case 0x177d8:case 0x272ea:case 0x272fa:if(events)fprintf(events,"{\"pc\":%u,\"nativeFrame\":%llu,\"completedFrame\":%llu,\"masterCycles\":%llu}\n",c.pc,(unsigned long long)c.vdp.frames,(unsigned long long)c.vdp.rendered_frames,(unsigned long long)c.master_cycles);break;default:break;}if(!em_web_campaign_observe(&c)&&!em_web_menu_select_observe(&mouse,&c))dune_mouse_observe(&mouse,&c);machine_step(&c);check(!c.fault,"native flow");if(trace&&last!=c.vdp.rendered_frames){last=c.vdp.rendered_frames;fprintf(trace,"%s\n",em_web_campaign_report(&c));}}
static void frames(unsigned n){uint64_t end=c.vdp.frames+n;while(c.vdp.frames<end)step();}
static void boundary(void){uint64_t end=c.vdp.frames+1000;while(!em_web_campaign.transition_ready&&c.vdp.frames<end)step();check(em_web_campaign.transition_ready,"native target reached completed ready raster");check(!em_web_campaign.fade_active&&c.vdp.rendered_frames>em_web_campaign.fade_end_render,"target ready only after actual native fade return and fresh completed frame");}
static void building(void){load("../dune-web/data/evidence/mission-atreides-01.cpu.bin");frames(4);unsigned gen=0;uint64_t end=c.vdp.frames+500;while(!gen&&c.vdp.frames<end){if(!mouse.count)dune_mouse_world_click(&mouse,&c,784,1136,DUNE_CLICK_SELECT);step();gen=(unsigned)em_web_campaign.transition_generation;}check(gen&&em_web_campaign.transition_kind==1&&em_web_campaign_world_hold(&c),"building intent precedes native first fade");check(!em_web_campaign.fade_active,"entry marker occurs before palette fade call");before=c;check(em_web_frame_hold_active(&c)&&em_web_frame_present(&c)!=c.vdp.frame,"native RGB frozen before entry");check(!em_web_campaign_transition_ack(&c,gen+1),"stale ack rejected");check(!memcmp(&before,&c,sizeof c),"host hold and stale ack CPU immutable");boundary();check(em_web_campaign_transition_active(&c)&&em_web_campaign_world_hold(&c),"ready remains active and holds map until host cover ack");check(em_web_campaign_scene_ready(&c)&&dune_mouse_context(&c)==2,"actual production screen ready after native palette setup");unsigned ready=(unsigned)c.vdp.frames;frames(5);check(em_web_campaign.transition_ready&&em_web_campaign.transition_generation==gen,"ready sticky across frames");before=c;check(em_web_campaign_transition_ack(&c,gen)&&!em_web_campaign_transition_active(&c)&&!em_web_frame_hold_active(&c),"cover ack releases RGB only");check(!memcmp(&before,&c,sizeof c),"ack changes no native CPU fields");dune_mouse_click(&mouse,&c,48,60,DUNE_CLICK_SELECT);end=c.vdp.frames+200;while(em_web_campaign.transition_generation==gen&&c.vdp.frames<end)step();check(em_web_campaign.transition_kind==2&&em_web_campaign.transition_generation==gen+1,"original Exit creates exactly one outgoing generation");gen++;check(!em_web_campaign_world_visible(&c)&&em_web_frame_hold_active(&c),"old BUI held while map unavailable");boundary();check(!em_web_campaign_world_visible(&c)&&em_web_campaign_transition_active(&c),"map remains hidden until own generation cover");before=c;check(em_web_campaign_transition_ack(&c,gen)&&em_web_campaign_world_visible(&c),"native map ready plus ack releases adapted world");check(!memcmp(&before,&c,sizeof c),"exit ack read-only native machine");printf("PASS continuous Yard entry/exit: generation%u sticky ready, before-first-fade hold, CPU-immutable acks; entry ready at%u\n",gen,ready);fflush(stdout);
 /* A real restored Starport uses the same original Exit handlers. */
 load(".local/building-ui-fixtures/house1-building11.cpu.bin");frames(4);check(dune_mouse_context(&c)==3&&em_web_campaign_scene_ready(&c),"restored Starport readiness established at post-setup poll");dune_mouse_click(&mouse,&c,48,60,DUNE_CLICK_SELECT);end=c.vdp.frames+500;while(!em_web_campaign.transition_generation&&c.vdp.frames<end)step();check(em_web_campaign.transition_kind==2,"native Starport Exit transition");boundary();check(em_web_campaign_transition_ack(&c,(unsigned)em_web_campaign.transition_generation)&&em_web_campaign_world_visible(&c),"Starport exact native exit/fade/map ready");puts("PASS original Starport exit full native transition");fflush(stdout);}
static void password(void){load(".local/campaign-scenes/house1-mission01-victory-results.cpu.bin");frames(4);check(em_web_campaign.poll_source==0x272d2,"native results ready");check(em_web_campaign_input_request(&c,0,PAD_A),"one results Continue");unsigned scroll=0,changed=0,oldstats=0;uint64_t prior=UINT64_MAX,end=c.vdp.frames+500;unsigned min=65535,max=0;while(c.vdp.frames<end){step();if(em_web_campaign_password_presentation(&c)&&prior!=c.vdp.rendered_frames){prior=c.vdp.rendered_frames;unsigned sy=c.vdp.vsram[0]&1023;if(sy<min)min=sy;if(sy>max)max=sy;before=c;const uint8_t*p=em_web_frame_textless(&c,3);check(p!=NULL&&!memcmp(&before,&c,sizeof c),"scroll compositor CPU immutable");++scroll;unsigned pixels=0,kept=0;for(unsigned y=0;y<224;y++)for(unsigned x=0;x<320;x++){unsigned sx,sy,at=vdp_plane_address(&em_web_frame_vdp,0,x,y,&sx,&sy),pos=(y*320+x)*3;int incoming=!vdp_window_at(&em_web_frame_vdp,x,y)&&at>=0xee00&&at<0xfc00;if(memcmp(p+pos,c.vdp.frame+pos,3)){check(incoming,"only incoming password plane-A cells removed");++pixels;}else if(!incoming&&(c.vdp.frame[pos]||c.vdp.frame[pos+1]||c.vdp.frame[pos+2]))++kept;}changed+=pixels>0;oldstats+=kept>100;if(scroll%12==1){char path[256];snprintf(path,sizeof path,".local/transitions/password-%03u.rgb",scroll);FILE*f=fopen(path,"wb");check(f!=NULL,"scroll RGB proof");fwrite(p,1,320*224*3,f);fclose(f);}}if(em_web_campaign.poll_source==0x272fa&&em_web_campaign_scene_ready(&c))break;}check(scroll>20&&changed>5&&oldstats>5&&max>min+100,"full native vertical scroll preserves old counters and moving clean underlay");check(em_web_campaign.input_seq==1&&dune_word(&c,0xc050)==0,"one Continue cannot skip password or start next mission");printf("PASS native password scroll: %u completed frames, %u cleaned incoming, VSRAM%u..%u, original stats pixels retained%u frames\n",scroll,changed,min,max,oldstats);fflush(stdout);}
static void title(void){memset(&c,0,sizeof c);c.rom=rom_data;c.rom_size=sizeof rom_data;c.audio_mode=AUDIO_MUTE;c.sr=0x2700;c.io_tx[0]=c.io_tx[1]=0xff;c.io_tx[2]=0xfb;c.a[7]=read_mem(&c,0,4);c.ssp=c.a[7];c.pc=read_mem(&c,4,4)&0xffffff;memset(&mouse,0,sizeof mouse);mouse.enabled=1;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);em_web_campaign.frontend_hold=1;uint64_t end=10000,first=0,prior=UINT64_MAX;unsigned falseframes=0,trueframes=0;while(c.vdp.frames<end){step();if(prior!=c.vdp.rendered_frames){prior=c.vdp.rendered_frames;if(em_web_campaign_title_license_ready(&c)){if(!first)first=c.vdp.frames;check(em_web_campaign.title_end_generation==em_web_campaign.scene_generation&&em_web_frame_license_visible,"license requires native end marker and actually visible native ink");++trueframes;}else ++falseframes;}if(em_web_campaign.main_ready_generation&&em_web_campaign_scene_ready(&c)&&trueframes>5)break;}check(first&&falseframes>100&&trueframes>5,"cold startup credits gated until authentic license visible");printf("PASS genuine cold title license first ready frame%llu; early frames hidden%u; native visible frames%u\n",(unsigned long long)first,falseframes,trueframes);}
int main(void){mkdir(".local/transitions",0755);events=fopen(".local/transitions/events.jsonl","w");trace=fopen(".local/transitions/continuous.jsonl","w");check(trace!=NULL,"transition trace");building();password();title();fclose(trace);fclose(events);return 0;}
